"""Independent additive modules; reads frozen v5 and never writes it."""
import json, pathlib, sys
P=pathlib.Path(__file__).parent
s=json.loads((P.parent/'revision-v5/scenario.json').read_text()); s['id']='mars-story-expansion-candidate'
items={i['id']:i for i in s['items']}; modules=[]
def item(k,label,desc,**kw): items[k]=dict(id=k,label=label,description=desc,**kw)
def recipe(k,a,b,out,label,desc,**kw):
 item(out,label,desc);s['recipes'].append(dict(id=k,a=a,b=b,out=out,description=desc,**kw))
def place(k,label,desc):s['locations'].append(dict(id=k,label=label,description=desc));return k
def module(k,after,title,motivation,stock,goals,locations,narrative):
 st=dict(id=k,title=title,speaker='Survey crew',motivation=motivation,area=dict(id='area-'+k,label=title,travelText='We gather the known equipment for this nearby work. The larger expedition remains at its current camp or depot.'),locations=locations,caches=[dict(id=k+'-cache',label='Known expedition equipment',narrative=narrative,items=stock)],objectives=[dict(id=k+'-'+g,kind='create',item=g,text=items[g]['label']) for g in goals])
 modules.append(dict(id=k,after=after,stage=st))
def stock(k,label,desc):item(k,label,desc);return k
# 1: follow people's memory, recover their ordinary shared life, not another machine.
loc=place('cargo-shoulder','Cargo shoulder','A low, accessible shoulder beside the refuge route, not a cliff rescue. The crew left a tagged camp-furniture sled here when their drive failed.')
ss=[stock('sled-padding','Sled padding','The crew recovery kit includes protective webbing pads.'),stock('tagged-cargo-sled','Tagged cargo sled','The crew identifies its abandoned sled. The sealed cargo is a folding mess table, not arbitrary life-saving machinery.'),stock('picture-roll','Picture roll','Personal photographs from the recovered crew’s cabin, intended for their shared table.')]
recipe('cargo-photo','field-camera','@'+loc,'cargo-view','Cargo view','Photograph the shoulder: the tagged sled is visible, but a direct route crosses loose ground.')
