recipe('contrast-scale','gravel-view','scale-card','scaled-gravel-view','Scaled gravel view','Add the in-scene scale reference to the image record so the pebble dimensions can be interpreted; capture and annotation are compressed.')
recipe('contrast-pair','ripple-view','scaled-gravel-view','paired-terrain-views','Paired terrain views','Put the two source views beside each other: similar-looking surface patterns need not share one origin.')
recipe('contrast-context','paired-terrain-views','terrain-model','deposition-context','Deposition context','Place both sites on the terrain model; grain context and layer geometry matter more than a ripple silhouette.')
recipe('contrast-revise','deposition-context','basin-field-record','qualified-basin-story','Qualified basin story','Revise the earlier account: the gravel supports ancient transport by water; the rippled surface alone does not. We have an evidence-weighted history, not a life detection.')
recipe('contrast-impression','ripple-cast-sheet','@'+loc1,'ripple-impression','Ripple impression','Take a small dry impression preserving the ripple surface’s shape without pretending it is a water signature.')
recipe('contrast-chip','loose-gravel-chip','specimen-log','logged-gravel-chip','Logged gravel chip','Attach the existing log’s precise ledge provenance to the already loose chip.')
recipe('contrast-board','qualified-basin-story','context-board','comparison-board','Comparison board','Mount the paired interpretation on the board with separate source positions and explicit uncertainty.')
item('comparison-case','Comparison case','The same two-cell case preserves the shape impression and a separately sourced gravel specimen.',capabilities=['comparison-specimens'],slots=[dict(id='ripple',accepts=['ripple-impression'],required=True),dict(id='gravel',accepts=['logged-gravel-chip'],required=True)])
# Use supplied shell itself as the stable object, not an extra assembly operation.
items['two-cell-case'].update(capabilities=['comparison-specimens'],slots=items['comparison-case']['slots'])
for sl,k in [('ripple','ripple-impression'),('gravel','logged-gravel-chip')]:s['recipes'].append(dict(id='contrast-pack-'+sl,a='two-cell-case',b=k,install=dict(target='two-cell-case',slot=sl,component=k),description='Put the '+k+' in its own labelled compartment of the same case.'))
recipe('contrast-archive','comparison-board','comparison-sleeve','sleeved-comparison','Sleeved comparison','Protect the annotated comparison for the journey home. The separate specimen case retains its source labels.')
module('contrast','buried-story','Not every ripple is a river','The new core supports our basin story, but a nearby ripple pattern looks suspiciously familiar. Compare the two exposures before we tell Earth they mean the same thing.',ss,['sleeved-comparison'],[loc1,loc2],'The existing geology team’s single comparison kit holds a board, two-cell case, dry impression sheet and document sleeve. The loose chip is explicitly from the adjacent gravel ledge, not supplied as a laboratory conclusion.')
modules[-1]['stage']['objectives'].append(dict(id='contrast-specimens',kind='create',capability='comparison-specimens',text='Keep the two differently sourced specimens distinct.'))
# 4: navigation with disagreement, physical wayfinding, and a matched hardware payoff.
loc=place('depot-marker-line','Depot marker line','The depot approach has permanent survey sockets. Dust has hidden paint, and fresh wandering dark tracks cross the old straight service route.')
ss=[stock('depot-survey-print','Depot survey print','The crew’s original engineering survey of the ascent depot approach, recovered from its navigation locker.'),stock('marker-cleaning-pad','Marker cleaning pad','A soft ready cleaning pad from the depot maintenance locker.'),stock('folded-route-sign','Folded route sign','An intact folding directional sign stored with the depot survey sockets.'),stock('sign-foot','Sign foot','The matching weighted base for the stored route sign.'),stock('depot-hauler','Depot hauler','The standard mission electric cargo hauler, intact except for the controller removed during storage. Its service plate explicitly lists the spare motor-controller model protected at the weather station.'),stock('hauler-platform','Hauler platform','The hauler’s cargo platform, removed for storage as one engineered unit.')]
