for sl,k in [('controller','protected-controller'),('platform','hauler-platform')]:s['recipes'].append(dict(id='depot-hauler-'+sl,a='depot-hauler',b=k,install=dict(target='depot-hauler',slot=sl,component=k),description='Fit the documented compatible '+k+' into the same depot hauler; no improvised avionics or chemistry.'))
