items['cushioned-capsule']['slots'].extend([dict(id='comparison',accepts=['two-cell-case'],required=True),dict(id='comparison-record',accepts=['sleeved-comparison'],required=True)])
for sl,k in [('comparison','two-cell-case'),('comparison-record','sleeved-comparison')]:s['recipes'].append(dict(id='expansion-return-'+sl,a='cushioned-capsule',b=k,install=dict(target='cushioned-capsule',slot=sl,component=k),description='Pack the separately sourced comparison evidence into the existing return capsule.'))
# Personal portrait is filed beside the technical archive, not made a flight prerequisite.
