next(st for st in s['stages'] if st['id']=='departure')['objectives'].append(dict(id='departure-family',kind='create',item='family-record',text='Keep the crew’s portrait for the journey home.'))
# Explicit timeline premise: the crop is supplemental during a restored mission, not emergency food.
next(st for st in s['stages'] if st['id']=='garden')['motivation']='Both crews are safely sheltered. Mission control confirms we can resume our original multi-month surface stay before the planned return, supported by the camp’s mission-provisioned food and certified life support. The greenhouse crop is fresh food to share, not a race against starvation. Restore its bed, light and water loop.'
# Payoffs replace existing downstream inputs rather than adding another status ladder.
for r in s['recipes']:
 if r['id']=='departure-10-secured-cart':
  r['a']='depot-cargo-shuttle';r['description']='Fit the cargo strap to the recovered depot hauler that we brought along the surveyed approach.'
 if r['id']=='departure-5-geology-archive':
  r['a']='family-record';r['retire']=[dict(item='family-record',reason='The recorder containing the personal portrait now also holds the geology archive.')]
 if r['id']=='departure-8-camp-handover-beacon':r['description']='Leave the next crew the maintenance card, including the living nursery and the restored greenhouse fittings, at the camp beacon.'
for st in s['stages']:
 for c in st.get('caches',[]):c['items']=[k for k in c['items'] if k!='transfer-cart']
